import React from "react";
import classes from "./header.css";
export const header = () => {
  return (
    <header className={classes.header}>
      <div>
        <p>Коннект</p>
        <ul>
          <li>голосование</li>
          <li>афиша</li>
          <li>обсуждения</li>
        </ul>
        <button>
          <p>войти</p>
        </button>
      </div>
    </header>
  );
};
